-- SLA compliance by priority for eligible tickets
-- Tables: tickets, sla_policies
WITH e AS (SELECT t.*, p.target_resolution_minutes, CASE WHEN t.resolved_at IS NOT NULL THEN (julianday(t.resolved_at)-julianday(t.created_at))*1440 WHEN t.created_at <= datetime('now','-1 minute') THEN (julianday('now')-julianday(t.created_at))*1440 END AS elapsed FROM tickets t JOIN sla_policies p ON p.policy_id=t.policy_id) SELECT priority, COUNT(*) AS eligible_tickets, SUM(CASE WHEN resolved_at IS NOT NULL AND elapsed<=target_resolution_minutes THEN 1 ELSE 0 END) AS met, SUM(CASE WHEN resolved_at IS NOT NULL AND elapsed>target_resolution_minutes THEN 1 ELSE 0 END) AS missed_resolved, SUM(CASE WHEN resolved_at IS NULL AND elapsed>target_resolution_minutes THEN 1 ELSE 0 END) AS overdue_open, ROUND(100.0*SUM(CASE WHEN resolved_at IS NOT NULL AND elapsed<=target_resolution_minutes THEN 1 ELSE 0 END)/COUNT(*),2) AS sla_compliance_rate FROM e GROUP BY priority ORDER BY sla_compliance_rate;
